class EqualTopSortedMergeRule:
    name = "equal_top_sorted_merge"

    def __init__(
        self,
        max_source_height: int = 64,
        min_destination_free_slots_after: int = 0,
        prefer_emptying_source_bonus: float = 1.0,
    ):
        self.max_source_height = int(max_source_height)
        self.min_destination_free_slots_after = int(min_destination_free_slots_after)
        self.prefer_emptying_source_bonus = float(prefer_emptying_source_bonus)

    def _is_allowed(self, partial, action) -> bool:
        so = action.so
        sd = action.sd

        if so == sd:
            return False

        hs = partial.h(so)
        hd = partial.h(sd)

        if hs <= 0 or hd >= partial.H:
            return False

        if hs > self.max_source_height:
            return False

        if partial.e(sd) - 1 < self.min_destination_free_slots_after:
            return False

        if hd <= 0:
            return False

        if partial.g(so) != partial.g(sd):
            return False

        return True

    def allowed(self, partial, memory, candidates):
        feasible = [a for a in candidates if self._is_allowed(partial, a)]
        feasible.sort(key=lambda a: self.score(partial, memory, a))
        return feasible

    def score(self, partial, memory, action):
        so = action.so
        sd = action.sd

        source_after = partial.h(so) - 1
        dest_after = partial.h(sd) + 1

        score = 0.0

        if source_after == 0:
            score -= self.prefer_emptying_source_bonus

        if hasattr(partial, "is_sorted_stack"):
            try:
                if partial.is_sorted_stack(sd):
                    score -= 0.25
                if partial.is_sorted_stack(so):
                    score -= 0.10
            except Exception:
                pass

        score += 0.02 * source_after
        score += 0.001 * dest_after
        return score


def build_component(
    problem,
    max_source_height: int = 64,
    min_destination_free_slots_after: int = 0,
    prefer_emptying_source_bonus: float = 1.0,
):
